#include "stdlib/blas/ext/base/ndarray/scircshift.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>

int main( void ) {
	// Create a data buffer for the input vector:
	float dataX[] = { 1.0f, 2.0f, 3.0f, 4.0f, 5.0f };

	// Specify the number of array dimensions:
	const int64_t ndimsX = 1;

	// Specify the array shape:
	int64_t shapeX[] = { 5 };

	// Specify the array strides:
	int64_t stridesX[] = { STDLIB_NDARRAY_FLOAT32_BYTES_PER_ELEMENT };

	// Specify the byte offset:
	const int64_t offset = 0;

	// Specify the array order:
	const enum STDLIB_NDARRAY_ORDER order = STDLIB_NDARRAY_ROW_MAJOR;

	// Specify the index mode:
	const enum STDLIB_NDARRAY_INDEX_MODE imode = STDLIB_NDARRAY_INDEX_ERROR;

	// Specify the subscript index modes:
	int8_t submodes[] = { STDLIB_NDARRAY_INDEX_ERROR };
	const int64_t nsubmodes = 1;

	// Create an input ndarray:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *x = stdlib_ndarray_allocate( STDLIB_NDARRAY_FLOAT32, (uint8_t *)dataX, ndimsX, shapeX, stridesX, offset, order, imode, nsubmodes, submodes );

	// Create a data buffer for an ndarray containing the number of positions to shift:
	const int64_t kdata[] = { 2 };

	// Specify the array strides for a zero-dimensional ndarray:
	int64_t kstrides[] = { 0 };

	// Create an ndarray containing the shift amount:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *k = stdlib_ndarray_allocate( STDLIB_NDARRAY_INT64, (uint8_t *)kdata, 0, NULL, kstrides, 0, order, imode, nsubmodes, submodes );

	if ( x == NULL || k == NULL ) {
		fprintf( stderr, "Error allocating memory.\n" );
		exit( 1 );
	}

	// Define a list of ndarrays:
	const struct ndarray *arrays[] = { x, k };

	// Perform computation:
	stdlib_blas_ext_scircshift( arrays );

	// Print the result:
	for ( int i = 0; i < 5; i++ ) {
		printf( "x[ %i ] = %f\n", i, dataX[ i ] );
	}

	// Free allocated memory:
	stdlib_ndarray_free( x );
	stdlib_ndarray_free( k );
}
